import pandas as pd
import matplotlib.pyplot as plt
import base64
from io import BytesIO
import seaborn as sns

def get_base64_image(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight')
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{img_str}"

def generate_report():
    # Load data
    df = pd.read_csv('/app/benchmark/data.csv')

    # Fix BOM character in App column if present
    if '\ufeffApp' in df.columns:
        df.rename(columns={'\ufeffApp': 'App'}, inplace=True)
    elif '﻿App' in df.columns: # sometimes it shows up differently
        df.rename(columns={'﻿App': 'App'}, inplace=True)

    # Calculate KPIs
    kpi_star_rating = df.groupby('App')['Star_Rating'].mean()
    kpi_sentiment = df.groupby('App')['Sentiment_Polarity'].mean()

    # Complaint Theme Rate
    theme_counts = df.groupby(['App', 'Review_Theme']).size().unstack(fill_value=0)
    theme_rates = theme_counts.div(theme_counts.sum(axis=1), axis=0) * 100

    # Mismatch Rate
    # Positive star (>=4) but negative polarity (<0)
    # Negative star (<=2) but positive polarity (>0)
    df['Mismatch'] = (
        ((df['Star_Rating'] >= 4) & (df['Sentiment_Polarity'] < -0.1)) |
        ((df['Star_Rating'] <= 2) & (df['Sentiment_Polarity'] > 0.1))
    )
    kpi_mismatch = df.groupby('App')['Mismatch'].mean() * 100

    # Average Engagement
    kpi_engagement_app = df.groupby('App')['Thumbs_Up_Count'].mean()
    kpi_engagement_theme = df.groupby('Review_Theme')['Thumbs_Up_Count'].mean()

    # Visualizations
    sns.set_theme(style="whitegrid")

    # 1. Cross-App Sentiment Comparison (Bar Chart)
    fig1, ax1 = plt.subplots(figsize=(10, 6))
    kpi_star_rating.sort_values().plot(kind='barh', ax=ax1, color='skyblue')
    ax1.set_title('Average Star Rating by App', fontsize=16)
    ax1.set_xlabel('Average Star Rating')
    ax1.set_ylabel('')
    img_stars = get_base64_image(fig1)

    fig1b, ax1b = plt.subplots(figsize=(10, 6))
    kpi_sentiment.sort_values().plot(kind='barh', ax=ax1b, color='lightgreen')
    ax1b.set_title('Mean Sentiment Polarity by App', fontsize=16)
    ax1b.set_xlabel('Mean Sentiment Polarity')
    ax1b.set_ylabel('')
    img_sentiment = get_base64_image(fig1b)

    # 2. Thematic Complaint Analysis
    fig2, ax2 = plt.subplots(figsize=(12, 7))
    complaint_themes = theme_rates[['Accuracy', 'Bugs', 'Pricing']]
    complaint_themes.plot(kind='bar', stacked=True, ax=ax2, colormap='viridis')
    ax2.set_title('Complaint Theme Breakdown by App (%)', fontsize=16)
    ax2.set_xlabel('')
    ax2.set_ylabel('Percentage of Reviews')
    plt.xticks(rotation=45)
    img_themes = get_base64_image(fig2)

    # 3. Sentiment-Rating Divergence
    fig3, ax3 = plt.subplots(figsize=(10, 6))
    kpi_mismatch.sort_values().plot(kind='barh', ax=ax3, color='salmon')
    ax3.set_title('Sentiment-Rating Mismatch Rate (%)', fontsize=16)
    ax3.set_xlabel('Mismatch Rate (%)')
    ax3.set_ylabel('')
    img_mismatch = get_base64_image(fig3)

    # 4. Review Depth & Emotion
    fig4, ax4 = plt.subplots(figsize=(10, 6))
    sns.scatterplot(data=df.sample(2000), x='Word_Count', y='Sentiment_Polarity', hue='Star_Rating', palette='coolwarm', alpha=0.6, ax=ax4)
    ax4.set_title('Review Length vs. Sentiment Polarity (Sampled)', fontsize=16)
    img_depth = get_base64_image(fig4)

    html = f'''
