                    </div>
                    <div class="chart-container">
                        <img src="{img_sentiment}" alt="Mean Sentiment Polarity by App">
                    </div>
                </div>
                <table>
                    <thead>
                        <tr>
                            <th>Application</th>
                            <th>Average Star Rating</th>
                            <th>Mean Sentiment Polarity</th>
                        </tr>
                    </thead>
                    <tbody>
                        {"".join(f"<tr><td>{app}</td><td>{kpi_star_rating[app]:.2f} / 5.0</td><td>{kpi_sentiment[app]:.3f}</td></tr>" for app in kpi_star_rating.index)}
                    </tbody>
                </table>
            </section>

            <!-- Thematic Complaint Analysis -->
            <section id="thematic-complaint-analysis">
                <h2>Thematic Complaint Analysis by Application</h2>
                <p>The following breakdown highlights the distribution of specific complaints (Pricing, Bugs, Accuracy) relative to general reviews. This reveals the specific operational weaknesses of each competitor.</p>
                <div class="chart-container">
                    <img src="{img_themes}" alt="Complaint Theme Breakdown by App">
                </div>
                <table>
                    <thead>
                        <tr>
                            <th>Application</th>
                            <th>Accuracy Complaints</th>
                            <th>Bug Complaints</th>
                            <th>Pricing Complaints</th>
                            <th>General Feedback</th>
                        </tr>
