                </div>
            </section>

            <!-- Review Depth & Emotional Intensity -->
            <section id="review-depth-emotion">
                <h2>Review Depth & Emotional Intensity</h2>
                <p>Analysis shows that users who are highly dissatisfied or highly satisfied tend to write longer, more detailed reviews. Negative sentiment often correlates with higher word counts as users detail their specific issues or bugs.</p>
                <div class="chart-container">
                    <img src="{img_depth}" alt="Review Length vs Sentiment Polarity">
                </div>
                <table>
                    <thead>
                        <tr>
                            <th>Review Theme</th>
                            <th>Average Engagement (Thumbs Up)</th>
                        </tr>
                    </thead>
                    <tbody>
                        {"".join(f"<tr><td>{theme}</td><td>{kpi_engagement_theme[theme]:.2f}</td></tr>" for theme in kpi_engagement_theme.index)}
                    </tbody>
                </table>
            </section>

